    log.info(f\"\\n{'='*60}\")\n        log.info(f\"MODEL: {awq_id}\")\n        log.info(f\"{'='*60}\")\n        judge = VLLMJudge(\n            model_path=model_cfg[\"awq_path\"],\n            model_id=awq_id,\n            gpu_id=GPU_ID,\n            quantization=\"awq\",\n        )\n        judge.load()\n        run_single_model(judge, awq_id, all_pairs, precomputed)\n        judge.unload()\n\n        # FP16\n        fp16_id = f\"{model_name}-fp16\"\n        log.info(f\"\\n{'='*60}\")\n        log.info(f\"MODEL: {fp16_id}\")\n        log.info(f\"{'='*60}\")\n        judge = VLLMJudge(\n            model_path=model_cfg[\"fp16_path\"],\n            model_id=fp16_id,\n            gpu_id=GPU_ID,\n            quantization=None,\n        )\n        judge.load()\n        run_single_model(judge, fp16_id, all_pairs, precomputed)\n        judge.unload()"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":2147,"cache_read_input_tokens":112812,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":2147},"output_tokens":2,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"2f5c3149-cd80-4777-99a0-3c047fda8c72","uuid":"1b7dee02-2615-4d93-91d5-61784a35daca"}
